import type { Resource } from "@/types";

/**
 * Curated learning resources.
 *
 * Rules (see CONTENT_GUIDE.md):
 *  - Only real resources from their original publishers. Never invent URLs.
 *  - `cost` must be accurate. "free-audit" = course free to audit, certificate paid.
 *  - `verified: true` only after the link has actually been checked.
 *    YouTube entries below were checked with YouTube's oEmbed service on 2026-11-24.
 *    Run `npm run check:links` to check every link.
 */

type ResourceInput = Omit<Resource, "language" | "addedAt" | "verified"> &
  Partial<Pick<Resource, "language" | "addedAt" | "verified">>;

const ADDED = "2026-11-24";

function r(input: ResourceInput): Resource {
  return { language: "English", addedAt: ADDED, verified: false, ...input };
}

